Roughly how many goroutines exist at peak in each?

func fetch(timeout time.Duration) (string, error) {
	ch := make(chan string)
	go func() { time.Sleep(50 * time.Millisecond); ch <- "quote" }()
	select {
	case q := <-ch: return q, nil
	case <-time.After(timeout): return "", errors.New("timeout")
	}
}

for i := 0; i < 1000; i++ { fetch(time.Millisecond) }
time.Sleep(200 * time.Millisecond)
fmt.Println(runtime.NumGoroutine())

